}

function find(quacks) {
  let isFind = false;

  let index = 0;
  const quack_index = new Array(5).fill(-1);

  for (let i = 0; i < quacks.length; i++) {
    if (quacks[i] == "quack"[index]) {
      quack_index[index++] = i;
    }

    if (index == 5) {
      isFind = true;

      for (let j of quack_index) {
        quacks[j] = "";
      }

      index = 0;
    }
  }

  return isFind;
}

